UPDATE utility_bills SET invoice_number=(SELECT invoice_number FROM luce WHERE luce.amount_cents=utility_bills.amount_cents), period_start=(SELECT period_start FROM luce WHERE luce.amount_cents=utility_bills.amount_cents), period_end=(SELECT period_end FROM luce WHERE luce.amount_cents=utility_bills.amount_cents), consumption=(SELECT consumption FROM luce WHERE luce.amount_cents=utility_bills.amount_cents), consumption_unit='kWh', notes=(SELECT notes FROM luce WHERE luce.amount_cents=utility_bills.amount_cents) WHERE service IN ('Luce','Energia elettrica','Elettricità') AND invoice_number IS NULL AND amount_cents IN (SELECT amount_cents FROM luce);--> statement-breakpoint
