INSERT INTO movements (kind,description,category,amount_cents,person,common_account,date) SELECT 'Spesa','Luce · Iren','Utenze',l.amount_cents,l.person,l.common_account,l.issued FROM luce l WHERE NOT EXISTS (SELECT 1 FROM utility_bills u WHERE u.invoice_number=l.invoice_number OR (u.service IN ('Luce','Energia elettrica','Elettricità') AND u.amount_cents=l.amount_cents));--> statement-breakpoint
