INSERT INTO utility_bills (movement_id,provider,service,amount_cents,wallet,common_account,date,recurring,period_start,period_end,consumption,consumption_unit,invoice_number,notes) SELECT m.id,'Iren','Luce',l.amount_cents,l.wallet,l.common_account,l.issued,0,l.period_start,l.period_end,l.consumption,'kWh',l.invoice_number,l.notes FROM luce l JOIN movements m ON m.description='Luce · Iren' AND m.amount_cents=l.amount_cents AND m.date=l.issued WHERE NOT EXISTS (SELECT 1 FROM utility_bills u WHERE u.invoice_number=l.invoice_number OR (u.service IN ('Luce','Energia elettrica','Elettricità') AND u.amount_cents=l.amount_cents));--> statement-breakpoint
INSERT INTO common_account_transactions (account,direction,description,category,amount_cents,date,source_movement_id) SELECT 'BBVA Utenze','Spesa','Luce · Iren','Utenze',u.amount_cents,u.date,u.movement_id FROM utility_bills u WHERE u.invoice_number IN ('38502604117818','38502605721031','38502606772090','38502608390884','38502609619786') AND NOT EXISTS (SELECT 1 FROM common_account_transactions c WHERE c.source_movement_id=u.movement_id);
